require_once __DIR__.'/includes/panel_helpers.php';exigirRol([1]);require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: medicos_moderno.php');exit;}$token=$_POST['csrf_token']??'';if(!is_string($token)||empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(403);exit('Solicitud no válida.');}
$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$nombres=trim((string)($_POST['nombres']??''));$apellidos=trim((string)($_POST['apellidos']??''));$licencia=trim((string)($_POST['numero_licencia']??''));$telefono=trim((string)($_POST['telefono']??''));$correo=trim((string)($_POST['correo']??''));$consultorio=trim((string)($_POST['consultorio']??''));$sede=trim((string)($_POST['sede']??''));$especialidades=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['especialidades']??[])))));
if(!$id||$nombres===''||$apellidos===''||$licencia===''||!$especialidades||mb_strlen($nombres)>100||mb_strlen($apellidos)>100||mb_strlen($licencia)>80||($correo!==''&&!filter_var($correo,FILTER_VALIDATE_EMAIL))){header('Location: editar_medico.php?id='.(int)$id.'&error=datos');exit;}
try{$pdo=conectarBD();$pdo->beginTransaction();$v=$pdo->prepare('SELECT id FROM medicos WHERE id=:id FOR UPDATE');$v->execute(['id'=>$id]);if(!$v->fetch())throw new RuntimeException('Médico no encontrado.');$d=$pdo->prepare('SELECT id FROM medicos WHERE id<>:id AND (LOWER(numero_licencia)=LOWER(:licencia) OR (:correo IS NOT NULL AND LOWER(correo)=LOWER(:correo))) LIMIT 1');$d->execute(['id'=>$id,'licencia'=>$licencia,'correo'=>$correo!==''?$correo:null]);if($d->fetch()){ $pdo->rollBack();header('Location: editar_medico.php?id='.$id.'&error=duplicado');exit;}$placeholders=implode(',',array_fill(0,count($especialidades),'?'));$v=$pdo->prepare("SELECT COUNT(*) FROM especialidades WHERE activo=TRUE AND id IN ($placeholders)");$v->execute($especialidades);if((int)$v->fetchColumn()!==count($especialidades))throw new DomainException('Especialidad inválida.');$u=$pdo->prepare('UPDATE medicos SET nombres=:nombres,apellidos=:apellidos,numero_licencia=:licencia,telefono=:telefono,correo=:correo,consultorio=:consultorio,sede=:sede,updated_at=now() WHERE id=:id');$u->execute(['nombres'=>$nombres,'apellidos'=>$apellidos,'licencia'=>$licencia,'telefono'=>$telefono!==''?$telefono:null,'correo'=>$correo!==''?mb_strtolower($correo):null,'consultorio'=>$consultorio!==''?$consultorio:null,'sede'=>$sede!==''?$sede:null,'id'=>$id]);$pdo->prepare('DELETE FROM medicos_especialidades WHERE medico_id=:id')->execute(['id'=>$id]);$i=$pdo->prepare('INSERT INTO medicos_especialidades(medico_id,especialidad_id) VALUES(:medico,:especialidad)');foreach($especialidades as $e)$i->execute(['medico'=>$id,'especialidad'=>$e]);$pdo->commit();$_SESSION['csrf_token']=bin2hex(random_bytes(32));header('Location: medicos_moderno.php?actualizado=1');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());header('Location: editar_medico.php?id='.(int)$id.'&error=servidor');}exit;
